$ python -c "
import docx
path = r'C:\Users\27063\Desktop\工具箱\论文降低aigc分析文献库\免费_Word标红版_AIGC检测报告_[标题未输入].docx'
doc = docx.Document(path)
stats = {'red':0,'orange':0,'purple':0,'black':0,'gray':0}
total = 0
for p in doc.paragraphs:
    if not p.text.strip(): continue
    for run in p.runs:
        if not run.text.strip(): continue
        total += len(run.text.strip())
        if run.font.color and run.font.color.rgb:
            r,g,b = run.font.color.rgb[0], run.font.color.rgb[1], run.font.color.rgb[2]
            if r>150 and g<100 and b<100: stats['red']+=len(run.text.strip())
            elif r>150 and g>100 and b<80: stats['orange']+=len(run.text.strip())
            elif r>100 and g<100 and b>100: stats['purple']+=len(run.text.strip())
            elif r<50 and g<50 and b<50: stats['black']+=len(run.text.strip())
        else: stats['gray']+=len(run.text.strip())

print(f'总:{total}字')
for k,v in sorted(stats.items(), key=lambda x:-x[1]):
    label={'red':'🔴>70%','orange':'🟠60-70%','purple':'🟣50-60%','black':'⚫<50%通过','gray':'⬜不检测'}[k]
    print(f'  {label}: {v}字({v/total*100:.1f}%)')
print(f'\\n黑色通过率: {stats[\"black\"]/total*100:.1f}%')
"
